using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using StockFlow.Data;
using StockFlow.Models;
namespace StockFlow.Controllers;
[Authorize]
public class ProductsController(ApplicationDbContext db) : Controller
{
    public async Task<IActionResult> Index(string? q, string? category, bool lowOnly = false) { var query = db.Products.AsQueryable(); if (!string.IsNullOrWhiteSpace(q)) query = query.Where(p => p.Name.Contains(q) || p.Sku.Contains(q) || (p.Barcode != null && p.Barcode.Contains(q))); if (!string.IsNullOrWhiteSpace(category)) query = query.Where(p => p.Category == category); if (lowOnly) query = query.Where(p => p.QuantityOnHand <= p.ReorderLevel); ViewBag.Query = q; ViewBag.Category = category; ViewBag.LowOnly = lowOnly; ViewBag.Categories = await db.Products.Select(p => p.Category).Distinct().OrderBy(x => x).ToListAsync(); return View(await query.OrderBy(p => p.Name).ToListAsync()); }
    [Authorize(Roles = "Admin,Manager,StockClerk,Procurement")] public IActionResult Create() => View(new Product());
    [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,StockClerk,Procurement")] public async Task<IActionResult> Create(Product p) { if (await db.Products.AnyAsync(x => x.Sku == p.Sku)) ModelState.AddModelError(nameof(p.Sku), "SKU already exists."); if (!ModelState.IsValid) return View(p); p.CreatedAt = DateTime.UtcNow; db.Products.Add(p); await db.SaveChangesAsync(); db.StockMovements.Add(new StockMovement { ProductId = p.Id, Type = MovementType.Opening, QuantityChange = p.QuantityOnHand, BalanceAfter = p.QuantityOnHand, Reason = "Initial stock on product creation", Reference = p.Sku, PerformedBy = User.Identity?.Name ?? "unknown" }); db.AuditLogs.Add(new AuditLog { UserEmail = User.Identity?.Name ?? "unknown", Action = "Created", EntityName = "Product", EntityId = p.Id.ToString(), Details = $"Created {p.Sku} - {p.Name}" }); await db.SaveChangesAsync(); TempData["Success"] = "Product created."; return RedirectToAction(nameof(Index)); }
    [Authorize(Roles = "Admin,Manager,StockClerk,Procurement")] public async Task<IActionResult> Edit(int id) { var p = await db.Products.FindAsync(id); return p == null ? NotFound() : View(p); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,StockClerk,Procurement")] public async Task<IActionResult> Edit(int id, Product p) { if (id != p.Id) return BadRequest(); if (await db.Products.AnyAsync(x => x.Sku == p.Sku && x.Id != id)) ModelState.AddModelError(nameof(p.Sku), "SKU already exists."); if (!ModelState.IsValid) return View(p); var old = await db.Products.FindAsync(id); if (old == null) return NotFound(); old.Sku = p.Sku; old.Name = p.Name; old.Category = p.Category; old.Description = p.Description; old.CostPrice = p.CostPrice; old.SellingPrice = p.SellingPrice; old.ReorderLevel = p.ReorderLevel; old.Barcode = p.Barcode; old.IsActive = p.IsActive; db.AuditLogs.Add(new AuditLog { UserEmail = User.Identity?.Name ?? "unknown", Action = "Updated", EntityName = "Product", EntityId = id.ToString(), Details = $"Updated {p.Sku}" }); await db.SaveChangesAsync(); TempData["Success"] = "Product updated."; return RedirectToAction(nameof(Index)); }
    [Authorize(Roles = "Admin,Manager,StockClerk")] public async Task<IActionResult> Adjust(int id) { var p = await db.Products.FindAsync(id); if (p == null) return NotFound(); ViewBag.Product = p; return View(new AdjustmentVm { ProductId = id }); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,StockClerk")] public async Task<IActionResult> Adjust(AdjustmentVm vm) { var p = await db.Products.FindAsync(vm.ProductId); if (p == null) return NotFound(); ViewBag.Product = p; if (!ModelState.IsValid || vm.QuantityChange == 0 || p.QuantityOnHand + vm.QuantityChange < 0) { ModelState.AddModelError("", vm.QuantityChange == 0 ? "Enter a non-zero adjustment." : "Adjustment would result in negative stock or contains invalid values."); return View(vm); } p.QuantityOnHand += vm.QuantityChange; db.StockMovements.Add(new StockMovement { ProductId = p.Id, Type = vm.QuantityChange > 0 ? MovementType.AdjustmentIncrease : MovementType.AdjustmentDecrease, QuantityChange = vm.QuantityChange, BalanceAfter = p.QuantityOnHand, Reason = vm.Reason, Reference = "ADJ-" + Guid.NewGuid().ToString("N")[..8].ToUpper(), PerformedBy = User.Identity?.Name ?? "unknown" }); db.AuditLogs.Add(new AuditLog { UserEmail = User.Identity?.Name ?? "unknown", Action = "Stock adjusted", EntityName = "Product", EntityId = p.Id.ToString(), Details = vm.Reason }); await db.SaveChangesAsync(); TempData["Success"] = "Stock adjustment saved to movement history."; return RedirectToAction(nameof(Index)); }
}
